     & -zab2(j2,j1,j3,j6)**2/(za(j1,j2)*zb(j5,j6)*zab2(j3,j1,j2,j4)**2)
     & *Lsm1_2mh(s(j3,j4),t(j1,j2,j3),s(j1,j2),s(j5,j6))

