#include <LRcalc.hpp>
#include <complex>
#include <FArray.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

void LRcalc(int k1, int k2, int k3, int k4, int k5, int k6,
            FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
            FArray1D<std::complex<double>>& A,
            FArray2D<std::complex<double>>& Xpp, FArray2D<std::complex<double>>& Xmp,
            FArray2D<std::complex<double>>& Xpm, FArray2D<std::complex<double>>& Xmm) {

    // ---statement functions
    auto zab2 = [&za, &zb](int k1, int k2, int k3, int k4) {
        return za(k1,k2)*zb(k2,k4)+za(k1,k3)*zb(k3,k4);
    };
    auto zba2 = [&za, &zb](int k1, int k2, int k3, int k4) {
        return zb(k1,k2)*za(k2,k4)+zb(k1,k3)*za(k3,k4);
    };
    // ---end statement functions

    double s12 = sprods_com_mod::s(k1,k2);
    double s34 = sprods_com_mod::s(k3,k4);
    double s56 = sprods_com_mod::s(k5,k6);

    for (int h3 = 1; h3 <= 2; h3++) {
        int l3, l4;
        if (h3 == 1) {
            l3 = k3;
            l4 = k4;
        } else if (h3 == 2) {
            l3 = k4;
            l4 = k3;
        }
        for (int h5 = 1; h5 <= 2; h5++) {
            int l5, l6;
            if (h5 == 1) {
                l5 = k5;
                l6 = k6;
            } else if (h5 == 2) {
                l5 = k6;
                l6 = k5;
            }

            Xmp(h3,h5) = (
                A(2)*s12*za(l3,l5)*zb(l4,l6)*zab2(k1,k3,k4,k2)/zab2(k2,k3,k4,k1)
                - (A(3)+A(4))*za(k1,l3)*za(k1,l5)*zb(k2,l4)*zb(k2,l6)
                + A(5)*zab2(k1,k3,k4,k2)
                  *(za(l3,l5)*zb(k2,l4)*zb(l6,k2)/zb(k1,k2)
                   +za(k1,l3)*za(k1,l5)*zb(l4,l6)/za(k1,k2))
            )/s34/s56/s12; // @coverage-probe

            Xpp(h3,h5) = za(l3,l5)/(za(k1,k2)*s12*s34*s56)*(
                +(A(3)+A(1))*s12*zb(k1,l6)*zb(l4,k2)
                -(A(4)+A(1))*s12*zb(k2,l6)*zb(l4,k1)
                +A(5)*(zb(k2,l4)*zb(k2,l6)*zab2(k2,k3,k4,k1)
                      -zb(k1,l4)*zb(k1,l6)*zab2(k1,k3,k4,k2))
            );

            // --- these are obtained by c.c. of above

            Xpm(3-h3,3-h5) = (
                A(2)*s12*zb(l3,l5)*za(l4,l6)*zba2(k1,k3,k4,k2)/zba2(k2,k3,k4,k1)
                - (A(3)+A(4))*zb(k1,l3)*zb(k1,l5)*za(k2,l4)*za(k2,l6)
                + A(5)*zba2(k1,k3,k4,k2)
                  *(zb(l3,l5)*za(k2,l4)*za(l6,k2)/za(k1,k2)
                   +zb(k1,l3)*zb(k1,l5)*za(l4,l6)/zb(k1,k2))
            )/s34/s56/s12;

            Xmm(3-h3,3-h5) = zb(l3,l5)/(zb(k1,k2)*s12*s34*s56)*(
                +(A(3)+A(1))*s12*za(k1,l6)*za(l4,k2)
                -(A(4)+A(1))*s12*za(k2,l6)*za(l4,k1)
                +A(5)*(za(k2,l4)*za(k2,l6)*zba2(k2,k3,k4,k1)
                      -za(k1,l4)*za(k1,l6)*zba2(k1,k3,k4,k2))
            );
        }
    }

    return;
}

extern "C" {
    void LRcalc_wrapper(int k1, int k2, int k3, int k4, int k5, int k6,
                         std::complex<double>* za_ptr, std::complex<double>* zb_ptr,
                         std::complex<double>* A_ptr,
                         std::complex<double>* Xpp_ptr, std::complex<double>* Xmp_ptr,
                         std::complex<double>* Xpm_ptr, std::complex<double>* Xmm_ptr) {
        FArray2D<std::complex<double>> za(za_ptr, mxpart, mxpart);
        FArray2D<std::complex<double>> zb(zb_ptr, mxpart, mxpart);
        FArray1D<std::complex<double>> A(A_ptr, 6);
        FArray2D<std::complex<double>> Xpp(Xpp_ptr, 2, 2);
        FArray2D<std::complex<double>> Xmp(Xmp_ptr, 2, 2);
        FArray2D<std::complex<double>> Xpm(Xpm_ptr, 2, 2);
        FArray2D<std::complex<double>> Xmm(Xmm_ptr, 2, 2);

        LRcalc(k1, k2, k3, k4, k5, k6, za, zb, A, Xpp, Xmp, Xpm, Xmm);
    }
}

#include <cmath>
#include <complex>
#include <constants_mod.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <FArray.hpp>

using namespace constants_mod;
using namespace mxpart_mod;
using namespace sprods_com_mod;

// the matrix elements of the
// helicity amplitudes for the QCD process
// q(-p1)+qbar(-p2) --> l(p3)+abar(p4)+g(p5)+g(p6)
// multiplied by ((a+l)^2-M**2)/(a+l)^2/g^4
// one colour ordering only
// left-on quark line only
void subqcd(int i1, int i2, int i3, int i4, int i5, int i6,
            FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
            FArray2D<std::complex<double>>& amp) {

    double s156, s56, s256, s34;

    auto zba2 = [&](int i1, int i2, int i3, int i4) -> std::complex<double> {
        return zb(i1, i2) * za(i2, i4) + zb(i1, i3) * za(i3, i4);
    };

    auto zba3 = [&](int i1, int i2, int i3, int i4, int i5) -> std::complex<double> {
        return zb(i1, i2) * za(i2, i5) + zb(i1, i3) * za(i3, i5) + zb(i1, i4) * za(i4, i5);
    };

    s156 = s(i1, i5) + s(i1, i6) + s(i5, i6);
    s256 = s(i2, i5) + s(i2, i6) + s(i5, i6);
    s56 = s(i5, i6);
    s34 = s(i3, i4);

    amp(-1, -1) = -four / s(i3, i4) * zb(i1, i4) * zba3(i1, i2, i6, i5, i3) / zb(i1, i5) / zb(i2, i6) / zb(i6, i5); // @coverage-probe
    amp(+1, +1) = +four / s(i3, i4) * za(i2, i3) * zba3(i4, i1, i6, i5, i2) / za(i1, i5) / za(i2, i6) / za(i6, i5);
