#ifndef ACALC_H
#define ACALC_H

#include <complex>
#include <FArray.hpp>

void Acalc(int k1, int k2, int k3, int k4, int k5, int k6, double mt,
           FArray1D<std::complex<double>>& A);

extern "C" {
  void Acalc_wrapper(int k1, int k2, int k3, int k4, int k5, int k6, double mt,
                      std::complex<double>* A_ptr);
}

#endif

//
//  SPDX-License-Identifier: GPL-3.0-or-later
