//

#include <Acalc.hpp>
#include <cmath>
#include <complex>
#include <constants_mod.hpp>
#include <sprods_com_mod.hpp>
#include <ZZclabels_mod.hpp>
#include <ZZdlabels_mod.hpp>
#include <ggZZintegrals_mod.hpp>
#include <FArray.hpp>

using namespace constants_mod;
using namespace sprods_com_mod;
using namespace ZZclabels_mod;
using namespace ZZdlabels_mod;
using namespace ggZZintegrals_mod;

void Acalc(int k1, int k2, int k3, int k4, int k5, int k6, double mt,
           FArray1D<std::complex<double>>& A) {

    double mtsq, s12, s134, s234, s134bar, s234bar, p3sq, Y;

    mtsq = std::pow(mt, 2);
    s12 = s(k1, k2);
    s134bar = s(k1, k3) + s(k1, k4);
    s234bar = s(k2, k3) + s(k2, k4);
    p3sq = s(k3, k4);
    s234 = s234bar + p3sq;
    s134 = s134bar + p3sq;
    Y = s134bar * s234bar - s12 * p3sq;

    A(1) = half * mtsq / s12 * (
        + two * C0(c1_34) * s134bar
        + two * C0(c2_56) * (-s234bar - s12)
        + two * C0(c2_34) * s234bar
        + two * C0(c1_56) * (-s12 - s134bar)
        - two * Y * D0(d1_34_2)
        + s12 * (s12 - 4.0 * mtsq) * (D0(d1_2_34) + D0(d2_1_34) + D0(d1_34_2))
    ); // @coverage-probe

    A(2) = two * mtsq * (D0(d6_1_2_34) + D0(d6_2_1_34) + C0(c12_34)
        + mtsq * (D0(d1_2_34) + D0(d2_1_34) - D0(d1_34_2)));

    A(3) = half * mtsq * s12 * (D0(d1_2_34) - D0(d2_1_34) - D0(d1_34_2));
    A(4) = half * mtsq * s12 * (D0(d2_1_34) - D0(d1_2_34) - D0(d1_34_2));

    A(5) = half * mtsq * s12 / (s134 * s234) * (
        + two * s134 * D0(d6_1_2_34) + two * s234 * D0(d6_2_1_34)
        - s134 * s234 * D0(d1_34_2)
        + four * mtsq * (s134 * D0(d1_2_34) + s234 * D0(d2_1_34))
        + two * (s234 + s134) * C0(c12_34)
    );

    A(6) = czip;

    return;
}

extern "C" {
    void Acalc_wrapper(int k1, int k2, int k3, int k4, int k5, int k6, double mt,
                        std::complex<double>* A_ptr) {
        FArray1D<std::complex<double>> A(A_ptr, 6);

        Acalc(k1, k2, k3, k4, k5, k6, mt, A);
    }
}

